=== FILE: tb/tb_irq_ctrl.sv ===
// Self-checking testbench for irq_ctrl (task prj-486b52a6aa:testbench).
// Requirement req-efb85c3b8e: verify the existing interrupt controller RTL.
// Expected behaviour is taken from interface_spec.md, not from the RTL:
//   * every directed check compares against a constant computed by hand from the spec;
//   * a behavioural reference model (irq_ctrl_ref, below), written from the spec, is
//     compared against each DUT after every clock edge, over all four registers.
// DUTs: N=8 (main), N=2 and N=32 (parameter limits, req IRQ-PARAM), sharing controls.
// Inputs change at the falling edge; outputs are sampled after the rising edge.
//
// Spec statement -> check group
//   IRQ-RESET            T1, T8   (remembered-level clear is not observable at the ports)
//   IRQ-REG-RW           T2
//   IRQ-PARAM            T2, T9
//   IRQ-READ             read sweep after every edge; all groups
//   IRQ-LEVEL            T3, T6, T7
//   IRQ-EDGE             T6
//   IRQ-DETECT-DISABLED  T3, T6
//   IRQ-W1C              T2, T4, T6
//   IRQ-ACK              T5, T9
//   IRQ-SET-WINS         T6, T7
//   IRQ-MASK             T3, T5, T6
//   IRQ-PRIORITY         T5, T9
//   IRQ-CLAIM            T3, T5, T9
//   IRQ-LATENCY          checks immediately after the detecting edge; all groups
`timescale 1ns / 1ps

// ---------------------------------------------------------------------------
// Reference model written from interface_spec.md.
// ---------------------------------------------------------------------------
module irq_ctrl_ref #(
    parameter int N = 8
) (
    input  logic         clk,
    input  logic         rst_n,
    input  logic [N-1:0] src,
    input  logic         we,
    input  logic [1:0]   addr,
    input  logic [31:0]  wdata,
    output logic [31:0]  e_rdata,
    output logic         e_irq,
    output logic [4:0]   e_id
);
    // Bits N and up read as zero and ignore writes.
    localparam logic [31:0] MASK = 32'hFFFF_FFFF >> (32 - N);

    logic [31:0] en, md, pd, lvl;
    logic [31:0] s, nxt;

    // Lowest-numbered set bit wins; result {found, index}.
    function automatic logic [5:0] lowest(input logic [31:0] act);
        logic       found;
        logic [5:0] r;
        found = 1'b0;
        r     = 6'd0;
        for (int j = 0; j < 32; j++)
            if (!found && act[j]) begin
                found = 1'b1;
                r     = {1'b1, j[4:0]};
            end
        return r;
    endfunction

    always @(posedge clk) begin
        s        = 32'd0;
        s[N-1:0] = src;
        if (!rst_n) begin
            en  <= 32'd0;
            md  <= 32'd0;
            pd  <= 32'd0;
            lvl <= 32'd0;
        end else begin
            nxt = pd;
            // Clearing: PENDING write-1-to-clear, CLAIM write acknowledges one source.
            if (we && addr == 2'd2) nxt = nxt & ~(wdata & MASK);
            if (we && addr == 2'd3 && wdata[4:0] < N) nxt[wdata[4:0]] = 1'b0;
            // Detection (independent of ENABLE) wins over a clear at the same edge.
            for (int k = 0; k < N; k++)
                if (s[k] && (!md[k] || !lvl[k])) nxt[k] = 1'b1;
            pd <= nxt;
            if (we && addr == 2'd0) en <= wdata & MASK;
            if (we && addr == 2'd1) md <= wdata & MASK;
            lvl <= s;
        end
    end

    assign {e_irq, e_id} = lowest(pd & en);
    assign e_rdata = (addr == 2'd0) ? en :
                     (addr == 2'd1) ? md :
                     (addr == 2'd2) ? pd : {e_irq, 26'd0, e_id};
endmodule

// ---------------------------------------------------------------------------
// Top-level testbench.
// ---------------------------------------------------------------------------
module tb_irq_ctrl;
    logic        clk   = 1'b0;
    logic        rst_n = 1'b0;
    logic [31:0] src   = 32'd0;
    logic        we    = 1'b0;
    logic [1:0]  addr  = 2'd0;
    logic [31:0] wdata = 32'd0;

    wire  [31:0] rdata8, rdata2, rdata32;
    wire         irq8, irq2, irq32;
    wire  [4:0]  id8, id2, id32;
    wire  [31:0] rdata8_e, rdata2_e, rdata32_e;
    wire         irq8_e, irq2_e, irq32_e;
    wire  [4:0]  id8_e, id2_e, id32_e;

    irq_ctrl #(.N(8)) dut8 (
        .clk(clk), .rst_n(rst_n), .src(src[7:0]), .we(we), .addr(addr), .wdata(wdata),
        .rdata(rdata8), .irq(irq8), .irq_id(id8));
    irq_ctrl #(.N(2)) dut2 (
        .clk(clk), .rst_n(rst_n), .src(src[1:0]), .we(we), .addr(addr), .wdata(wdata),
        .rdata(rdata2), .irq(irq2), .irq_id(id2));
    irq_ctrl #(.N(32)) dut32 (
        .clk(clk), .rst_n(rst_n), .src(src), .we(we), .addr(addr), .wdata(wdata),
        .rdata(rdata32), .irq(irq32), .irq_id(id32));

    irq_ctrl_ref #(.N(8)) ref8 (
        .clk(clk), .rst_n(rst_n), .src(src[7:0]), .we(we), .addr(addr), .wdata(wdata),
        .e_rdata(rdata8_e), .e_irq(irq8_e), .e_id(id8_e));
    irq_ctrl_ref #(.N(2)) ref2 (
        .clk(clk), .rst_n(rst_n), .src(src[1:0]), .we(we), .addr(addr), .wdata(wdata),
        .e_rdata(rdata2_e), .e_irq(irq2_e), .e_id(id2_e));
    irq_ctrl_ref #(.N(32)) ref32 (
        .clk(clk), .rst_n(rst_n), .src(src), .we(we), .addr(addr), .wdata(wdata),
        .e_rdata(rdata32_e), .e_irq(irq32_e), .e_id(id32_e));

    always #50 clk = ~clk;

    int          n_pass = 0;
    int          n_fail = 0;
    bit          done   = 1'b0;
    string       nonce  = "";
    logic [31:0] rng    = 32'h2545_F491;
    logic [31:0] r1, r2, r3, r4, rsrc, rdat;
    logic        rrst, rwe;
    logic [1:0]  raddr;

    // Every compare counts as a pass or a fail.
    task automatic chk(input string what, input logic [31:0] got, input logic [31:0] exp);
        if (got === exp) n_pass++;
        else begin
            n_fail++;
            $display("FAIL [%0t] %s: got 0x%08h, expected 0x%08h", $time, what, got, exp);
        end
    endtask

    // Each DUT against its spec model: irq, irq_id and rdata at the current addr.
    task automatic cmp_models(input string where);
        chk({where, " N=8 irq"},     {31'd0, irq8},  {31'd0, irq8_e});
        chk({where, " N=8 irq_id"},  {27'd0, id8},   {27'd0, id8_e});
        chk({where, " N=8 rdata"},   rdata8,         rdata8_e);
        chk({where, " N=2 irq"},     {31'd0, irq2},  {31'd0, irq2_e});
        chk({where, " N=2 irq_id"},  {27'd0, id2},   {27'd0, id2_e});
        chk({where, " N=2 rdata"},   rdata2,         rdata2_e);
        chk({where, " N=32 irq"},    {31'd0, irq32}, {31'd0, irq32_e});
        chk({where, " N=32 irq_id"}, {27'd0, id32},  {27'd0, id32_e});
        chk({where, " N=32 rdata"},  rdata32,        rdata32_e);
    endtask

    // Read every register with no clock edge (IRQ-READ: rdata follows addr).
    task automatic sweep();
        we = 1'b0;
        for (int a = 0; a < 4; a++) begin
            addr = a[1:0];
            #1;
            cmp_models("read sweep");
        end
    endtask

    // One clock edge: drive at the falling edge, check after the rising edge.
    task automatic step_r(input logic r, input logic [31:0] s, input logic w,
                          input logic [1:0] a, input logic [31:0] d);
        @(negedge clk);
        rst_n = r;
        src   = s;
        we    = w;
        addr  = a;
        wdata = d;
        @(posedge clk);
        #1;
        cmp_models("after edge");
        sweep();
    endtask

    task automatic step(input logic [31:0] s, input logic w, input logic [1:0] a,
                        input logic [31:0] d);
        step_r(1'b1, s, w, a, d);
    endtask

    // Register write at the next edge, sources held at their current value.
    task automatic wr(input logic [1:0] a, input logic [31:0] d);
        step(src, 1'b1, a, d);
    endtask

    // Sources take value s at the next edge, no write.
    task automatic hold(input logic [31:0] s);
        step(s, 1'b0, 2'd0, 32'd0);
    endtask

    // Directed read with a hand-computed expected value.
    task automatic rd(input int n, input logic [1:0] a, input logic [31:0] exp, input string what);
        we   = 1'b0;
        addr = a;
        #1;
        if (n == 8)      chk({"N=8 ", what},  rdata8,  exp);
        else if (n == 2) chk({"N=2 ", what},  rdata2,  exp);
        else             chk({"N=32 ", what}, rdata32, exp);
    endtask

    // Directed check of irq and irq_id.
    task automatic irqchk(input int n, input logic eirq, input logic [4:0] eid, input string what);
        #1;
        if (n == 8) begin
            chk({"N=8 irq: ", what},    {31'd0, irq8},  {31'd0, eirq});
            chk({"N=8 irq_id: ", what}, {27'd0, id8},   {27'd0, eid});
        end else if (n == 2) begin
            chk({"N=2 irq: ", what},    {31'd0, irq2},  {31'd0, eirq});
            chk({"N=2 irq_id: ", what}, {27'd0, id2},   {27'd0, eid});
        end else begin
            chk({"N=32 irq: ", what},    {31'd0, irq32}, {31'd0, eirq});
            chk({"N=32 irq_id: ", what}, {27'd0, id32},  {27'd0, eid});
        end
    endtask

    // xorshift32, deterministic and simulator-independent.
    task automatic next_rnd(output logic [31:0] r);
        rng = rng ^ (rng << 13);
        rng = rng ^ (rng >> 17);
        rng = rng ^ (rng << 5);
        r   = rng;
    endtask

    initial begin
        if (!$value$plusargs("nonce=%s", nonce))
            if (!$value$plusargs("NONCE=%s", nonce))
                if (!$value$plusargs("nirmaan_nonce=%s", nonce))
                    if (!$value$plusargs("NIRMAAN_NONCE=%s", nonce))
                        $display("tb_irq_ctrl: no nonce plusarg found");

        // ---------------- T1: reset (IRQ-RESET) ----------------
        // Reset wins over a write and over detection at the same edge.
        step_r(1'b0, 32'hFFFF_FFFF, 1'b1, 2'd0, 32'hFFFF_FFFF);
        rd(8, 2'd0, 32'h0, "T1 ENABLE after reset");
        rd(8, 2'd1, 32'h0, "T1 MODE after reset");
        rd(8, 2'd2, 32'h0, "T1 PENDING after reset");
        rd(8, 2'd3, 32'h0, "T1 CLAIM after reset");
        irqchk(8, 1'b0, 5'd0, "T1 after reset");
        rd(2, 2'd2, 32'h0, "T1 PENDING after reset");
        rd(32, 2'd2, 32'h0, "T1 PENDING after reset");
        rd(32, 2'd0, 32'h0, "T1 ENABLE after reset");
        step_r(1'b0, 32'd0, 1'b0, 2'd0, 32'd0);
        hold(32'd0);
        rd(8, 2'd2, 32'h0, "T1 PENDING after release, sources low");

        // ---------------- T2: register access (IRQ-REG-RW, IRQ-PARAM, IRQ-W1C) ----------------
        wr(2'd0, 32'h0000_00A5);
        rd(8, 2'd0, 32'h0000_00A5, "T2 ENABLE write/read");
        rd(8, 2'd1, 32'h0,         "T2 MODE unchanged by ENABLE write");
        rd(8, 2'd2, 32'h0,         "T2 PENDING unchanged by ENABLE write");
        wr(2'd1, 32'h0000_003C);
        rd(8, 2'd1, 32'h0000_003C, "T2 MODE write/read");
        rd(8, 2'd0, 32'h0000_00A5, "T2 ENABLE unchanged by MODE write");
        wr(2'd0, 32'hFFFF_FFFF);
        rd(8,  2'd0, 32'h0000_00FF, "T2 ENABLE upper bits read zero");
        rd(2,  2'd0, 32'h0000_0003, "T2 ENABLE upper bits read zero");
        rd(32, 2'd0, 32'hFFFF_FFFF, "T2 ENABLE all bits");
        wr(2'd1, 32'hFFFF_FF00);
        rd(8,  2'd1, 32'h0,         "T2 MODE upper bits ignore writes");
        rd(2,  2'd1, 32'h0,         "T2 MODE upper bits ignore writes");
        rd(32, 2'd1, 32'hFFFF_FF00, "T2 MODE all bits");
        wr(2'd2, 32'hFFFF_FFFF);
        rd(8,  2'd2, 32'h0, "T2 PENDING write never sets");
        rd(32, 2'd2, 32'h0, "T2 PENDING write never sets");
        irqchk(8, 1'b0, 5'd0, "T2 nothing pending");
        wr(2'd3, 32'h0000_0001);
        rd(8, 2'd0, 32'h0000_00FF, "T2 ENABLE unchanged by CLAIM write");
        rd(8, 2'd1, 32'h0,         "T2 MODE unchanged by CLAIM write");
        rd(8, 2'd2, 32'h0,         "T2 PENDING unchanged by CLAIM write");

        // ---------------- T3: level detection, disabled source, mask ----------------
        wr(2'd1, 32'h0);   // all high-level
        wr(2'd0, 32'h0);   // all disabled
        hold(32'h04);      // source 2 high for one edge
        rd(8, 2'd2, 32'h04, "T3 level source sets PENDING while disabled");
        irqchk(8, 1'b0, 5'd0, "T3 disabled source does not raise irq");
        rd(8, 2'd3, 32'h0,  "T3 CLAIM with irq low");
        hold(32'h0);
        rd(8, 2'd2, 32'h04, "T3 PENDING stays after source drops");
        wr(2'd0, 32'h04);
        irqchk(8, 1'b1, 5'd2, "T3 enabling a pending source raises irq");
        rd(8, 2'd3, 32'h8000_0002, "T3 CLAIM read");

        // ---------------- T4: write-1-to-clear (IRQ-W1C) ----------------
        wr(2'd2, 32'h0);
        rd(8, 2'd2, 32'h04, "T4 W1C of zero leaves PENDING");
        wr(2'd2, 32'hFFFF_FFFB);
        rd(8, 2'd2, 32'h04, "T4 W1C of other bits leaves bit 2");
        wr(2'd2, 32'h04);
        rd(8, 2'd2, 32'h0,  "T4 W1C clears bit 2");
        irqchk(8, 1'b0, 5'd0, "T4 irq low after clear");
        rd(8, 2'd3, 32'h0,  "T4 CLAIM after clear");

        // ---------------- T5: priority, acknowledge, mask, claim ----------------
        wr(2'd0, 32'hFF);
        hold(32'hA0); hold(32'h0);                 // sources 5 and 7
        rd(8, 2'd2, 32'hA0, "T5 PENDING two sources");
        irqchk(8, 1'b1, 5'd5, "T5 lowest of 5,7");
        rd(8, 2'd3, 32'h8000_0005, "T5 CLAIM 5");
        hold(32'h48); hold(32'h0);                 // sources 3 and 6
        rd(8, 2'd2, 32'hE8, "T5 PENDING four sources");
        irqchk(8, 1'b1, 5'd3, "T5 lowest of 3,5,6,7");
        wr(2'd3, 32'd3);
        rd(8, 2'd2, 32'hE0, "T5 ack 3 clears only bit 3");
        irqchk(8, 1'b1, 5'd5, "T5 next after ack 3");
        wr(2'd3, 32'd5);
        rd(8, 2'd2, 32'hC0, "T5 ack 5 clears only bit 5");
        irqchk(8, 1'b1, 5'd6, "T5 next after ack 5");
        wr(2'd0, 32'h7F);
        irqchk(8, 1'b1, 5'd6, "T5 source 7 masked, 6 enabled");
        wr(2'd0, 32'h3F);
        irqchk(8, 1'b0, 5'd0, "T5 pending sources all masked");
        rd(8, 2'd3, 32'h0,  "T5 CLAIM all masked");
        rd(8, 2'd2, 32'hC0, "T5 masking leaves PENDING");
        wr(2'd0, 32'h80);
        irqchk(8, 1'b1, 5'd7, "T5 only source 7 enabled");
        wr(2'd0, 32'hFF);
        irqchk(8, 1'b1, 5'd6, "T5 all enabled again");
        wr(2'd3, 32'd8);
        rd(8, 2'd2, 32'hC0, "T5 ack of N changes nothing");
        wr(2'd3, 32'd31);
        rd(8, 2'd2, 32'hC0, "T5 ack of 31 changes nothing");
        wr(2'd3, 32'hFFFF_FFE6);                   // bits 4:0 = 6
        rd(8, 2'd2, 32'h80, "T5 ack uses wdata bits 4:0 only");
        irqchk(8, 1'b1, 5'd7, "T5 after ack 6");
        hold(32'h01); hold(32'h0);                 // first and last source
        rd(8, 2'd2, 32'h81, "T5 PENDING sources 0 and 7");
        irqchk(8, 1'b1, 5'd0, "T5 source 0 beats 7");
        rd(8, 2'd3, 32'h8000_0000, "T5 CLAIM source 0");
        wr(2'd3, 32'd0);
        rd(8, 2'd2, 32'h80, "T5 ack 0");
        irqchk(8, 1'b1, 5'd7, "T5 source 7 after ack 0");
        rd(8, 2'd3, 32'h8000_0007, "T5 CLAIM source 7");
        wr(2'd3, 32'd7);
        rd(8, 2'd2, 32'h0, "T5 ack 7");
        irqchk(8, 1'b0, 5'd0, "T5 irq low, id 0");
        // Acknowledge one source while another is detected at the same edge.
        hold(32'h02); hold(32'h0);
        step(32'h01, 1'b1, 2'd3, 32'd1);
        rd(8, 2'd2, 32'h01, "T5 detect 0 and ack 1 at the same edge");
        irqchk(8, 1'b1, 5'd0, "T5 detect 0 and ack 1 at the same edge");
        hold(32'h0);
        wr(2'd2, 32'h01);
        rd(8, 2'd2, 32'h0, "T5 clear source 0");
        // Enable written at the same edge a source is detected.
        wr(2'd0, 32'h0);
        step(32'h10, 1'b1, 2'd0, 32'h10);
        irqchk(8, 1'b1, 5'd4, "T5 enable and detection at the same edge");
        rd(8, 2'd3, 32'h8000_0004, "T5 CLAIM source 4");
        hold(32'h0);
        wr(2'd2, 32'h10);
        wr(2'd0, 32'hFF);
        rd(8, 2'd2, 32'h0, "T5 end PENDING");

        // ---------------- T6: rising-edge detection (IRQ-EDGE) ----------------
        wr(2'd1, 32'h01);                          // source 0 rising edge; input low
        hold(32'h01);
        rd(8, 2'd2, 32'h01, "T6 rising edge sets PENDING");
        irqchk(8, 1'b1, 5'd0, "T6 edge source raises irq");
        step(32'h01, 1'b1, 2'd2, 32'h01);
        rd(8, 2'd2, 32'h0,  "T6 clear while held high, no new edge");
        hold(32'h01);
        rd(8, 2'd2, 32'h0,  "T6 held high sets only once");
        irqchk(8, 1'b0, 5'd0, "T6 held high, cleared");
        hold(32'h0);
        rd(8, 2'd2, 32'h0,  "T6 falling edge does not set");
        hold(32'h01);
        rd(8, 2'd2, 32'h01, "T6 second rising edge sets");
        wr(2'd3, 32'd0);                           // input still high
        rd(8, 2'd2, 32'h0,  "T6 ack of held edge source clears");
        hold(32'h0);
        step(32'h01, 1'b1, 2'd2, 32'h01);
        rd(8, 2'd2, 32'h01, "T6 rising edge wins over same-edge W1C");
        step(32'h01, 1'b1, 2'd3, 32'd0);
        rd(8, 2'd2, 32'h0,  "T6 ack while held clears");
        hold(32'h0);
        wr(2'd0, 32'hFE);                          // source 0 disabled
        hold(32'h01);
        rd(8, 2'd2, 32'h01, "T6 disabled edge source still detected");
        irqchk(8, 1'b0, 5'd0, "T6 disabled edge source no irq");
        hold(32'h0);
        wr(2'd0, 32'hFF);
        irqchk(8, 1'b1, 5'd0, "T6 enabling pending edge source");
        wr(2'd2, 32'h01);
        // Mixed modes: source 0 edge, source 1 level, both held high.
        hold(32'h03);
        rd(8, 2'd2, 32'h03, "T6 mixed modes both detected");
        step(32'h03, 1'b1, 2'd2, 32'h03);
        rd(8, 2'd2, 32'h02, "T6 W1C: held edge clears, held level stays");
        irqchk(8, 1'b1, 5'd1, "T6 mixed modes after W1C");
        hold(32'h0);
        rd(8, 2'd2, 32'h02, "T6 level PENDING sticky after drop");
        wr(2'd2, 32'h02);
        wr(2'd1, 32'h0);
        rd(8, 2'd2, 32'h0, "T6 end PENDING");

        // ---------------- T7: detection wins over clear (IRQ-SET-WINS) ----------------
        hold(32'h04);
        step(32'h04, 1'b1, 2'd3, 32'd2);
        rd(8, 2'd2, 32'h04, "T7 level ack while high stays pending");
        irqchk(8, 1'b1, 5'd2, "T7 level ack while high");
        step(32'h04, 1'b1, 2'd2, 32'h04);
        rd(8, 2'd2, 32'h04, "T7 level W1C while high stays pending");
        step(32'h0, 1'b1, 2'd3, 32'd2);
        rd(8, 2'd2, 32'h0,  "T7 ack after source drops clears");
        irqchk(8, 1'b0, 5'd0, "T7 irq low");

        // ---------------- T8: reset in the middle of operation ----------------
        hold(32'h30); hold(32'h0);
        irqchk(8, 1'b1, 5'd4, "T8 before reset");
        step_r(1'b0, 32'h0, 1'b0, 2'd0, 32'h0);
        rd(8, 2'd0, 32'h0, "T8 ENABLE cleared");
        rd(8, 2'd2, 32'h0, "T8 PENDING cleared");
        irqchk(8, 1'b0, 5'd0, "T8 irq low in reset");
        hold(32'h0);
        hold(32'h01);
        rd(8, 2'd2, 32'h01, "T8 MODE reset to level");
        irqchk(8, 1'b0, 5'd0, "T8 ENABLE reset to zero");
        hold(32'h0);
        wr(2'd2, 32'h01);

        // ---------------- T9: parameter limits N=2 and N=32 ----------------
        wr(2'd0, 32'hFFFF_FFFF);
        wr(2'd1, 32'h0);
        rd(2,  2'd0, 32'h0000_0003, "T9 ENABLE");
        rd(32, 2'd0, 32'hFFFF_FFFF, "T9 ENABLE");
        rd(8,  2'd0, 32'h0000_00FF, "T9 ENABLE");
        hold(32'h8000_0000); hold(32'h0);
        irqchk(32, 1'b1, 5'd31, "T9 source 31");
        rd(32, 2'd3, 32'h8000_001F, "T9 CLAIM source 31");
        rd(2,  2'd2, 32'h0, "T9 N=2 ignores source 31");
        irqchk(2, 1'b0, 5'd0, "T9 N=2 idle");
        rd(8,  2'd2, 32'h0, "T9 N=8 ignores source 31");
        hold(32'h02); hold(32'h0);
        irqchk(2, 1'b1, 5'd1, "T9 N=2 source 1");
        rd(2,  2'd3, 32'h8000_0001, "T9 CLAIM source 1");
        irqchk(32, 1'b1, 5'd1, "T9 N=32 source 1 beats 31");
        wr(2'd3, 32'd2);
        rd(2,  2'd2, 32'h02, "T9 ack 2 out of range for N=2");
        wr(2'd3, 32'd31);
        rd(32, 2'd2, 32'h02, "T9 ack 31 for N=32");
        rd(2,  2'd2, 32'h02, "T9 ack 31 out of range for N=2");
        wr(2'd3, 32'd1);
        rd(2,  2'd2, 32'h0, "T9 ack 1");
        rd(32, 2'd2, 32'h0, "T9 ack 1");
        rd(8,  2'd2, 32'h0, "T9 ack 1");
        irqchk(32, 1'b0, 5'd0, "T9 N=32 idle");

        // ---------------- T10: seeded random interaction (model-checked) ----------------
        for (int t = 0; t < 400; t++) begin
            next_rnd(r1);
            next_rnd(r2);
            next_rnd(r3);
            next_rnd(r4);
            rrst  = (r4[5:0] != 6'd0);             // reset about one edge in 64
            rwe   = (r4[7:6] != 2'b00);            // write on three edges in four
            raddr = r4[9:8];
            rsrc  = r1 & r2;                       // sparse sources
            rdat  = (raddr == 2'd3 && r4[10]) ? (r3 & 32'h7) : r3;
            step_r(rrst, rsrc, rwe, raddr, rdat);
        end
        hold(32'h0);
        hold(32'h0);

        done = 1'b1;
        $display("NIRMAAN-SIM %s %0d passed, %0d failed", nonce, n_pass, n_fail);
        $finish;
    end

    // Watchdog: report a failure if the sequence never completes.
    initial begin
        #2_000_000;
        if (!done) begin
            n_fail++;
            $display("FAIL [%0t] watchdog timeout", $time);
            $display("NIRMAAN-SIM %s %0d passed, %0d failed", nonce, n_pass, n_fail);
            $finish;
        end
    end
endmodule
